cd /workspace/project/wasd-clone && python3 << 'EOF'
# Read ReviewerAgent
with open('server/src/modules/swarm/services/ReviewerAgent.ts', 'r') as f:
    content = f.read()
# Add error tracking interface
old_import = '''import { Logger } from "../../../core/logger/Logger";
import { AIService } from "../../ai/services/AIService";'''
new_import = '''import { Logger } from "../../../core/logger/Logger";
import { AIService } from "../../ai/services/AIService";
/**
 * Error tracking per specific error signature.
 * FAILURE COUNT INCREMENTS ONLY FOR IDENTICAL ERRORS.
 */
interface ErrorSignature {
  errorKey: string;
  count: number;
  firstSeen: number;
  lastSeen: number;
}'''
# Replace imports
content = content.replace(old_import, new_import)
# Add tracking to class
old_class = '''export class ReviewerAgent {
  private readonly logger: Logger;
  private readonly aiService: AIService;
  constructor(aiService: AIService) {
    this.logger = new Logger("ReviewerAgent");
    this.aiService = aiService;
  }'''
new_class = '''export class ReviewerAgent {
  private readonly logger: Logger;
  private readonly aiService: AIService;

  // Per-error tracking: ONLY identical errors increment the counter
  private readonly errorRegistry: Map<string, ErrorSignature> = new Map();
  private readonly MAX_REPEATED_FAILURES = 5;
  private readonly FAILURE_WINDOW_MS = 300000;
  constructor(aiService: AIService) {
    this.logger = new Logger("ReviewerAgent");
    this.aiService = aiService;
  }
  /**
   * Track error - ONLY increments if EXACT same error repeats.
   */
  private trackError(errorMsg: string): boolean {
    const errorKey = this.hashError(errorMsg);
    const now = Date.now();
    const existing = this.errorRegistry.get(errorKey);
    if (existing) {
      if (now - existing.firstSeen > this.FAILURE_WINDOW_MS) {
        this.errorRegistry.set(errorKey, { errorKey, count: 1, firstSeen: now, lastSeen: now });
        return false;
      }
      existing.count++;
      existing.lastSeen = now;
      return existing.count >= this.MAX_REPEATED_FAILURES;
    }
    this.errorRegistry.set(errorKey, { errorKey, count: 1, firstSeen: now, lastSeen: now });
    return false;
  }
  private hashError(errorMsg: string): string {
    let hash = 0;
    for (let i = 0; i < errorMsg.length; i++) {
      const char = errorMsg.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return hash.toString(36);
  }'''
if old_class in content:
    content = content.replace(old_class, new_class)
    with open('server/src/modules/swarm/services/ReviewerAgent.ts', 'w') as f:
        f.write(content)
    print("SUCCESS")
else:
    print("NOT FOUND class")
EOF
